-- El runner añade primero los fixtures comunes de applications.sql, dentro de
-- una transacción exclusiva de rcfito_test. Nunca ejecutar contra operación.
do $$ begin if current_database()<>'rcfito_test' then raise exception 'Pruebas limitadas a rcfito_test'; end if; end $$;
do $$ declare i int; lot uuid; sub uuid; begin
  for i in 5..6 loop
    lot:=public.create_project_lot(jsonb_build_object('project_id',current_setting('test.project'),'field_id','30000000-0000-4000-8000-000000000001','code','LE'||i,'name','Lote edición '||i,'area_ha',5,'infrastructure_type_id','60000000-0000-4000-8000-000000000001'));
    select id into sub from public.lot_subdivisions where lot_id=lot;
    perform public.save_sowing_stage(jsonb_build_object('id',format('80000000-0000-4000-8000-%s',lpad(i::text,12,'0')),'subdivision_id',sub,'crop_id','40000000-0000-4000-8000-000000000001','variety_id','50000000-0000-4000-8000-000000000001','area_ha',5,'planned_sowing_date','2026-01-01'));
    perform public.transition_sowing_stage(format('80000000-0000-4000-8000-%s',lpad(i::text,12,'0'))::uuid,'planted','2026-01-02');
  end loop;
end $$;
select pg_temp.assert_true((select count(*)=0 from public.application_changes),'historial empieza vacío sin eventos inventados');
select public.create_application_order(pg_temp.order_data()||jsonb_build_object('application_number',23,'source_text',E'  Fuente original\nNota  ','observations',E'  Nota indicada\nOriginal  '),pg_temp.stages()||array['80000000-0000-4000-8000-000000000005','80000000-0000-4000-8000-000000000006']::uuid[],pg_temp.mixture());
create function pg_temp.edit_target(p_stage text) returns uuid language sql as $$select id from public.application_targets where stage_id=p_stage::uuid and order_id='90000000-0000-4000-8000-000000000001'$$;
create function pg_temp.edit_ids() returns uuid[] language sql as $$select array[pg_temp.edit_target('80000000-0000-4000-8000-000000000005'),pg_temp.edit_target('80000000-0000-4000-8000-000000000006')]$$;
create function pg_temp.revision_data(p_id text default 'a0000000-0000-4000-8000-000000000001',p_version int default 0) returns jsonb language sql as $$
  select jsonb_build_object('id',p_id,'order_id','90000000-0000-4000-8000-000000000001','expected_revision',p_version,'target_ids',pg_temp.edit_ids(),'method_id','71000000-0000-4000-8000-000000000001','indicated_date','2026-01-03','scheduled_date','2026-01-07','water_l_ha',150,'observations',E'  Nota revisada\nPrimera  ','reason','  Ajuste ficticio de indicación  ')
$$;
create function pg_temp.revision_products() returns jsonb language sql as $$select '[{"product_id":"72000000-0000-4000-8000-000000000001","dose":12},{"product_id":"72000000-0000-4000-8000-000000000003","dose":4}]'::jsonb$$;
create function pg_temp.correction_data(p_id text default 'b0000000-0000-4000-8000-000000000001',p_version int default 0) returns jsonb language sql as $$
  select jsonb_build_object('id',p_id,'target_id',pg_temp.edit_target('80000000-0000-4000-8000-000000000005'),'expected_version',p_version,'actual_date','2026-01-07','water_l_ha',160,'equipment','  Equipo corregido  ','applicator','  Aplicador ficticio  ','observations',E'  Nota real corregida\nPrimera  ','reason','  Corrección ficticia  ')
$$;
create function pg_temp.correction_products() returns jsonb language sql as $$select '[{"product_id":"72000000-0000-4000-8000-000000000003","dose":4},{"product_id":"72000000-0000-4000-8000-000000000004","dose":7}]'::jsonb$$;
select pg_temp.assert_true((select revision=0 from public.application_orders),'orden inicia en revisión cero');
select pg_temp.assert_true((select bool_and(indication_change_id is null and correction_version=0 and application_number=23) from public.application_targets),'destinos nuevos conservan número y versiones iniciales');
select public.perform_application_targets('90000000-0000-4000-8000-000000000001',array[pg_temp.edit_target('80000000-0000-4000-8000-000000000001')],'{"changed":false,"actual_date":"2026-01-04","equipment":"Equipo original"}');
select public.cancel_application_targets('90000000-0000-4000-8000-000000000001',array[pg_temp.edit_target('80000000-0000-4000-8000-000000000002')],'Cancelación ficticia original');
reset role;
